new='''    /// The ids of the stored stream pauses that echo the host's own ack pause, retracted from the store so the UI can drop their rows.
    fn retract_echoed_pauses(
        store: &mut Store,
        mission: &MissionId,
        events: &[Event],
        launch_id: &str,
    ) -> Vec<EventId> {
        let echoes_a_pause = events
            .iter()
            .any(|event| event.kind == EventKind::MissionPaused && !control::is_ack(&event.id));
        if !echoes_a_pause {
            return Vec::new();
        }
        store.retract_echoed_pauses(mission).unwrap_or_else(|err| {
            tracing::error!(%err, launch_id, "store");
            Vec::new()
        })
    }

'''
s=s[:i]+new+s[j:]
open(p,"w").write(s)
